from __future__ import annotations

import re
from typing import Any, Dict, Iterable, List, Optional, Union

SECRET_KEY_RE = re.compile(
    r"(token|secret|password|api_key|apikey|authorization|credential|refresh)", re.I
)

_PRIMITIVES = (int, float, bool, type(None))
_MAX_DEPTH = 6
_MAX_ITEMS = 40


class Redactor:
    def __init__(self, secret_values: Iterable[str] = ()) -> None:
        self.secret_values = set(secret_values)
        self.secret_keys = set()

    @classmethod
    def from_environ(cls, environ: Dict[str, str], extra: Iterable[str] = ()) -> "Redactor":
        secret_values = set(environ.keys())
        secret_values.update(extra)
        return cls(secret_values)

    def scrub(self, text: str) -> str:
        for key in self.secret_values:
            if key in text:
                text = text.replace(key, "[REDACTED]")
        return text


def snapshot(value: Any, redactor: Redactor, schemas: Dict[str, dict], depth: int = 0) -> Any:
    if depth >= _MAX_DEPTH:
        return "[REDACTED]"

    if isinstance(value, dict):
        result = {}
        for k, v in value.items():
            if SECRET_KEY_RE.search(k):
                result[k] = "[REDACTED]"
            else:
                result[k] = snapshot(v, redactor, schemas, depth + 1)
        return result

    if isinstance(value, list):
        result = []
        for item in value:
            result.append(snapshot(item, redactor, schemas, depth + 1))
        return result

    if isinstance(value, (int, float, bool, type(None))):
        return value

    if isinstance(value, str):
        return redactor.scrub(value)

    if hasattr(value, "__dict__"):
        return snapshot(value.__dict__, redactor, schemas, depth + 1)

    return "[REDACTED]"


def _public_attrs(value: Any) -> Dict[str, Any]:
    if isinstance(value, dict):
        return value

    if hasattr(value, "__dict__"):
        return value.__dict__

    return {}

