from __future__ import annotations

import time
from typing import Any, Dict, List, Optional


class Recorder:
    def __init__(self, now=None) -> None:
        self.calls: List[Dict] = []
        self.events: List[Dict] = []
        self.now = now or time.time

    def _stamp(self) -> float:
        return self.now()

    def record_call(self, container: str, method: str, cfg: dict) -> None:
        self.calls.append({
            "seq": len(self.calls),
            "dir": "out",
            "call": f"{container}.{method}",
            "args": cfg.get("args", []),
            "kwargs": cfg.get("kwargs", {}),
            "timestamp": self._stamp()
        })

    def record_event(self, source: str, event: str, payload: Any) -> None:
        self.events.append({
            "seq": len(self.events),
            "dir": "in",
            "source": source,
            "event": event,
            "payload": payload,
            "timestamp": self._stamp()
        })

    @property
    def call_count(self) -> int:
        return len(self.calls)

    @property
    def event_count(self) -> int:
        return len(self.events)

