from __future__ import annotations

import datetime as _dt
import json
from typing import Dict

from .recorder import Recorder

REQUIRED_KEYS = ("session", "timeline", "mocked_modules", "metadata")


def build_tape(recorder: Recorder, session_meta: dict) -> dict:
    tape = {
        "session": session_meta,
        "timeline": [],
        "mocked_modules": {},
        "metadata": {},
        "nested_schemas": {}
    }

    for call in recorder.calls:
        tape["timeline"].append({
            "seq": call["seq"],
            "dir": "out",
            "call": call["call"],
            "args": call["args"],
            "kwargs": call["kwargs"],
            "timestamp": call["timestamp"]
        })

    for event in recorder.events:
        tape["timeline"].append({
            "seq": event["seq"],
            "dir": "in",
            "source": event["source"],
            "event": event["event"],
            "payload": event["payload"],
            "timestamp": event["timestamp"]
        })

    return tape


def infer_hierarchical_bindings(container_paths) -> Dict[str, str]:
    bindings = {}
    for path in container_paths:
        parts = path.split(".")
        obj = {}
        for part in parts:
            obj = {part: obj}
        bindings.update(obj)
    return bindings


def validate_tape(tape: dict) -> None:
    for key in tape:
        if key not in REQUIRED_KEYS:
            raise ValueError(f"Invalid tape: unknown key {key}")

    for key in REQUIRED_KEYS:
        if key not in tape:
            raise ValueError(f"Missing required key {key} in tape")

    for call in tape["timeline"]:
        if "call" not in call:
            raise ValueError("Missing 'call' in timeline entry")

    for event in tape["timeline"]:
        if "source" not in event or "event" not in event:
            raise ValueError("Missing 'source' or 'event' in timeline entry")


def load_tape(path: str) -> dict:
    with open(path, "r") as f:
        return json.load(f)
